const response = pm.response.json();

const expectedStatus = Number(pm.iterationData.get("expectedStatus"));
const expectedMessage = pm.iterationData.get("expectedMessage");

pm.test("Status code matches expected", function () {
    pm.response.to.have.status(expectedStatus);
});

pm.test("Response is valid JSON", function () {
    pm.expect(response).to.be.an("object");
});

if (expectedStatus === 200) {

    pm.test("Access token is generated", function () {
        pm.expect(response.accessToken).to.be.a("string").and.not.empty;
    });

    pm.test("Username is correct", function () {
        pm.expect(response.username).to.eql("emilys");
    });

} else {

    pm.test("Expected error message is returned", function () {
        pm.expect(response.message).to.eql(expectedMessage);
    });

    pm.test("Access token is not returned", function () {
        pm.expect(response).to.not.have.property("accessToken");
    });
}
